var getArticleInfo = async (client, title) => {
  const response = await client.request("/w/api.php", {
    action: "query",
    format: "json",
    titles: title,
    prop: "revisions",
    rvprop: "timestamp|user",
    rvlimit: 1,
    rvdir: "newer"
  });
  const pages = response.query?.pages ?? {};
  const page = Object.values(pages)[0];
  if (!page || page.missing || !page.pageid) {
    return null;
  }
  const revision = page.revisions?.[0];
  if (!revision?.user || !revision.timestamp || !page.title) {
    return null;
  }
  return {
    pageId: page.pageid,
    title: page.title,
    creator: revision.user,
    createdAt: revision.timestamp
  };
};

