init_utils();

class OutreachSyncService {
  prisma;
  dashboardClient;
  constructor(prisma2, dashboardConfig) {
    this.prisma = prisma2;
    this.dashboardClient = new OutreachDashboardClient(dashboardConfig);
  }
  async syncEditorsFromDashboard(school, slug, options) {
    const parentJobId = options?.parentJobId;
    const startTime = Date.now();
    let jobId = null;
    const job = await this.prisma.syncJob.create({
      data: {
        jobType: "editors",
        status: "pending",
        parentJobId
      }
    });
    jobId = job.id;
    await this.prisma.syncJob.update({
      where: { id: jobId },
      data: {
        status: "running",
        startedAt: new Date
      }
    });
    try {
      const userData = await this.dashboardClient.getUsers(school, slug);
      const allUsers = userData.course?.users ?? userData.users ?? [];
      const users = allUsers.filter((user) => user.role === 0);
      let imported = 0;
      let updated = 0;
      const errorDetails = [];
      for (const user of users) {
        try {
          const normalizedUsername = this.normalizeUsername(user.username);
          const result2 = await this.prisma.editor.upsert({
            where: { username: normalizedUsername },
            create: {
              username: normalizedUsername,
              externalId: String(user.id),
              source: "outreach_dashboard",
              isActive: true
            },
            update: {
              externalId: String(user.id),
              source: "outreach_dashboard",
              isActive: true,
              updatedAt: new Date
            }
          });
          const createdJustNow = result2.createdAt.getTime() > startTime - 1000;
          if (createdJustNow) {
            imported++;
          } else {
            updated++;
          }
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : String(error);
          errorDetails.push({
            username: user.username,
            error: errorMessage
          });
        }
      }
      const result = {
        imported,
        updated,
        errors: errorDetails.length,
        errorDetails
      };
      if (jobId) {
        await this.prisma.syncJob.update({
          where: { id: jobId },
          data: {
            status: "completed",
            completedAt: new Date,
            metadata: result
          }
        });
      }
      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      if (jobId) {
        await this.prisma.syncJob.update({
          where: { id: jobId },
          data: {
            status: "failed",
            completedAt: new Date,
            error: errorMessage
          }
        });
      }
      throw error;
    }
  }
  async syncArticlesFromDashboard(school, slug) {
    try {
      const articleData = await this.dashboardClient.getArticles(school, slug);
      const articles = articleData.course?.articles ?? [];
      let imported = 0;
      let updated = 0;
      const errorDetails = [];
      for (const article of articles) {
        try {
          const result = await this.prisma.article.upsert({
            where: { outreachId: article.id || 0 },
            create: {
              pageId: 0,
              title: article.title || "",
              wikiProject: normalizeWikiProject(article.language || "en", article.project || "wikipedia"),
              source: "OUTREACH_DASHBOARD",
              outreachId: article.id || 0,
              url: article.url || "",
              characterSum: article.character_sum || 0,
              referencesCount: article.references_count || 0,
              isNewArticle: article.new_article || false,
              rating: article.rating || null
            },
            update: {
              title: article.title || "",
              wikiProject: normalizeWikiProject(article.language || "en", article.project || "wikipedia"),
              url: article.url || "",
              characterSum: article.character_sum || 0,
              referencesCount: article.references_count || 0,
              isNewArticle: article.new_article || false,
              rating: article.rating || null,
              updatedAt: new Date
            }
          });
          const createdJustNow = result.createdAt.getTime() > Date.now() - 5000;
          if (createdJustNow) {
            imported++;
          } else {
            updated++;
          }
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : String(error);
          errorDetails.push({
            username: article.title || "Unknown",
            error: errorMessage
          });
        }
      }
      const syncResult = {
        imported,
        updated,
        errors: errorDetails.length,
        errorDetails
      };
      return syncResult;
    } catch (error) {
      throw error;
    }
  }
  normalizeUsername(username) {
    return username.replace(/\s+/g, "_");
  }
}
// src/routes/stats.ts
var dashboardClient = new OutreachDashboardClient({
  baseUrl: "https://outreachdashboard.wmflabs.org"
});
var statsService = new StatsService(prisma);
var statsRoutes = new Hono2;
var parseFilters = (input) => {
  const parsed = StatsFilterSchema.parse(input);
  return {
    startDate: parsed.startDate ? new Date(parsed.startDate) : undefined,
    endDate: parsed.endDate ? new Date(parsed.endDate) : undefined,
    wikiProject: parsed.wikiProject,
    editorId: parsed.editorId,
    source: parsed.source
  };
};
statsRoutes.get("/overall", async (c) => {
  const filters = parseFilters(c.req.query());
  const totals = await statsService.getOverallStats(filters);
  const byWikiProject = await statsService.getStatsByWikiProject(filters);
  return c.json({
    success: true,
    data: {
      totals,
      byWikiProject
    },
    meta: {
      dateRange: {
        start: filters.startDate?.toISOString(),
        end: filters.endDate?.toISOString()
      },
      generatedAt: new Date().toISOString()
    }
  });
});
statsRoutes.get("/editors", async (c) => {
  const filters = parseFilters(c.req.query());
  const pagination = PaginationSchema.parse(c.req.query());
  const stats = await statsService.getStatsByEditor(filters);
  const startIndex = (pagination.page - 1) * pagination.limit;
  const paged = stats.slice(startIndex, startIndex + pagination.limit);
  return c.json({
    success: true,
    data: paged,
    meta: {
      total: stats.length,
      page: pagination.page,
      limit: pagination.limit
    }
  });
});
statsRoutes.get("/editors/:id", async (c) => {
  const filters = parseFilters({ ...c.req.query(), editorId: c.req.param("id") });
  const stats = await statsService.getStatsByEditor(filters);
  if (stats.length === 0) {
    return c.json({ success: false, error: { code: "not_found", message: "Editor not found" } }, 404);
  }
  return c.json({ success: true, data: stats[0] });
});
statsRoutes.get("/timeseries", async (c) => {
  const parsed = TimeSeriesSchema.parse(c.req.query());
  const filters = parseFilters(parsed);
  const granularity = parsed.granularity ?? "daily";
  const series = await statsService.getTimeSeries(filters, granularity);
  return c.json({ success: true, data: { granularity, series } });
});
statsRoutes.get("/dashboard", async (c) => {
  try {
    const [editorsCount, articlesCreated, articlesEdited, commonsUploads, articleSums, articles] = await Promise.all([
      prisma.editor.count({ where: { isActive: true } }),
      prisma.article.count({ where: { isNewArticle: true } }),
      prisma.article.count(),
      prisma.commonsUpload.count(),
      prisma.article.aggregate({
        _sum: {
          characterSum: true,
          referencesCount: true
        }
      }),
      prisma.article.findMany({
        select: {
          pageviews: {
            where: { type: "CUMULATIVE" },
            orderBy: { date: "desc" },
            take: 1,
            select: { cumulativeViews: true }
          }
        }
      })
    ]);
    const totalCharacterSum = articleSums._sum.characterSum ?? 0;
    const referencesAdded = articleSums._sum.referencesCount ?? 0;
    const wordsAdded = Math.round(totalCharacterSum / 6);
    const pageviews = articles.reduce((sum, article) => sum + (article.pageviews[0]?.cumulativeViews ?? 0), 0);
    return c.json({
      success: true,
      data: {
        editorsCount,
        articlesCreated,
        articlesEdited,
        totalEdits: articlesEdited,
        wordsAdded,
        referencesAdded,
        pageviews,
        commonsUploads
      }
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error fetching dashboard stats:", message);
    return c.json({
      success: false,
      error: "Failed to fetch dashboard stats",
      details: message
    }, 500);
  }
});
statsRoutes.get("/editors-list", async (c) => {
  try {
    const editors = await prisma.editor.findMany({
      where: { isActive: true },
      select: {
        id: true,
        username: true,
        articles: {
          select: {
            article: {
              select: {
                characterSum: true,
                referencesCount: true
              }
            }
          }
        },
        commonsUploads: {
          select: { id: true }
        }
      },
      orderBy: { username: "asc" }
    });
    const data = editors.map((editor) => {
      const characterSum = editor.articles.reduce((sum, entry) => sum + (entry.article?.characterSum ?? 0), 0);
      const referencesCount = editor.articles.reduce((sum, entry) => sum + (entry.article?.referencesCount ?? 0), 0);
      return {
        id: editor.id,
        username: editor.username,
        characterSum,
        referencesCount,
        uploadsCount: editor.commonsUploads.length
      };
    });
    return c.json({ success: true, data });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error fetching editor list stats:", message);
    return c.json({
      success: false,
      error: "Failed to fetch editor list stats",
      details: message
    }, 500);
  }
});
statsRoutes.get("/sync-status", async (c) => {
  try {
    const [
      localEditorsCount,
      localArticlesCount,
      localArticlesCreated,
      localSums,
      localArticles,
      lastSyncJob,
      externalCourse
    ] = await Promise.all([
      prisma.editor.count({ where: { isActive: true } }),
      prisma.article.count(),
      prisma.article.count({ where: { isNewArticle: true } }),
      prisma.article.aggregate({
        _sum: {
          characterSum: true,
          referencesCount: true
        }
      }),
      prisma.article.findMany({
        select: {
          pageviews: {
            where: { type: "CUMULATIVE" },
            orderBy: { date: "desc" },
            take: 1,
            select: { cumulativeViews: true }
          }
        }
      }),
      prisma.syncJob.findFirst({
        where: { status: "completed" },
        orderBy: { completedAt: "desc" },
        select: {
          id: true,
          jobType: true,
          completedAt: true,
          metadata: true
        }
      }),
      dashboardClient.getCourse("OKA", "OKA").catch(() => null)
    ]);
    const localPageviews = localArticles.reduce((sum, article) => sum + (article.pageviews[0]?.cumulativeViews ?? 0), 0);
    const localCharacterSum = localSums._sum.characterSum ?? 0;
    const localReferencesCount = localSums._sum.referencesCount ?? 0;
    const external2 = externalCourse?.course ? {
      editorsCount: externalCourse.course.student_count ?? 0,
      articlesCount: externalCourse.course.article_count ?? 0,
      articlesCreated: externalCourse.course.created_count ?? 0,
      totalEdits: parseInt(String(externalCourse.course.edit_count ?? "0").replace(/,/g, ""), 10) || 0,
      wordsAdded: parseInt(String(externalCourse.course.word_count ?? "0").replace(/,/g, ""), 10) || 0,
      referencesAdded: externalCourse.course.references_count ?? 0,
      pageviews: parseInt(String(externalCourse.course.view_count ?? "0").replace(/,/g, ""), 10) || 0,
      commonsUploads: externalCourse.course.upload_count ?? 0
    } : null;
    return c.json({
      success: true,
      data: {
        local: {
          editorsCount: localEditorsCount,
          articlesCount: localArticlesCount,
          articlesCreated: localArticlesCreated,
          characterSum: localCharacterSum,
          wordsAdded: Math.round(localCharacterSum / 6),
          referencesAdded: localReferencesCount,
          pageviews: localPageviews
        },
        external: external2,
        lastSync: lastSyncJob ? {
          jobType: lastSyncJob.jobType,
          completedAt: lastSyncJob.completedAt,
          metadata: lastSyncJob.metadata
        } : null,
        syncRequired: external2 !== null && (localEditorsCount === 0 || localArticlesCount === 0 || localEditorsCount < external2.editorsCount || localArticlesCount < external2.articlesCount)
      }
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error fetching sync status:", message);
    return c.json({
      success: false,
      error: "Failed to fetch sync status",
      details: message
    }, 500);
  }
});

