outreachRoutes.post("/articles/sync", async (c) => {
  try {
    const body = OutreachSyncSchema.parse(await c.req.json());
    const runningSync = await prisma.syncJob.findFirst({
      where: {
        jobType: "outreach_articles",
        status: "running"
      }
    });
    if (runningSync) {
      throw new Error("Sync already in progress");
    }
    const job = await prisma.syncJob.create({
      data: {
        jobType: "outreach_articles",
        status: "pending"
      }
    });
    setTimeout(async () => {
      try {
        const result = await outreachArticleSyncService2.syncArticlesFromDashboard(body.school, body.slug);
        await prisma.syncJob.update({
          where: { id: job.id },
          data: {
            status: "completed",
            completedAt: new Date,
            metadata: result
          }
        });
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        console.error("Outreach articles sync failed:", errorMessage);
        await prisma.syncJob.update({
          where: { id: job.id },
          data: {
            status: "failed",
            completedAt: new Date,
            error: errorMessage
          }
        });
      }
    }, 0);
    return c.json({
      success: true,
      data: {
        jobId: job.id,
        status: "accepted"
      }
    }, 202);
  } catch (error) {
    if (error instanceof SyntaxError) {
      return c.json({
        success: false,
        error: "Invalid request body"
      }, 400);
    }
    if (error instanceof Error && error.name === "ZodError") {
      return c.json({
        success: false,
        error: "Validation error",
        details: error.message
      }, 400);
    }
    if (error instanceof Error && error.message?.includes("Sync already in progress")) {
      return c.json({
        success: false,
        error: error.message
      }, 409);
    }
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error triggering outreach articles sync:", message);
    return c.json({
      success: false,
      error: "Failed to trigger sync",
      details: message
    }, 500);
  }
});
outreachRoutes.get("/articles/db", async (c) => {
  try {
    const query = OutreachArticlesQuerySchema.parse(c.req.query());
    const offset = (query.page - 1) * query.limit;
    const where = {
      source: "OUTREACH_DASHBOARD",
      ...query.search ? { title: { contains: query.search, mode: "insensitive" } } : {},
      ...query.wiki ? (() => {
        const [language, project] = query.wiki.split(".");
        if (language && project) {
          return { wikiProject: `${language}.${project}.org` };
        }
        return {};
      })() : {}
    };
    const total = await prisma.article.count({ where });
    const articles = await prisma.article.findMany({
      where,
      skip: offset,
      take: query.limit,
      include: {
        pageviews: { where: { type: "CUMULATIVE" }, orderBy: { date: "desc" }, take: 1 },
        editors: {
          include: {
            editor: true
          }
        }
      },
      orderBy: {
        createdAt: "desc"
      }
    });
    const totalPages = Math.ceil(total / query.limit);
    return c.json({
      success: true,
      data: {
        articles,
        pagination: {
          total,
          page: query.page,
          limit: query.limit,
          totalPages
        }
      }
    }, 200);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error fetching articles from database:", message);
    return c.json({
      success: false,
      error: "Failed to fetch articles",
      details: message
    }, 500);
  }
});
outreachRoutes.get("/articles/stats", async (c) => {
  try {
    const totalArticles = await prisma.article.count({
      where: { source: "OUTREACH_DASHBOARD" }
    });
    const articles = await prisma.article.findMany({
      where: { source: "OUTREACH_DASHBOARD" },
      include: {
        pageviews: {
          where: { type: "CUMULATIVE" },
          orderBy: { date: "desc" },
          take: 1
        }
      }
    });
    let totalPageviews = 0;
    for (const article of articles) {
      if (article.pageviews.length > 0 && article.pageviews[0].cumulativeViews) {
        totalPageviews += article.pageviews[0].cumulativeViews;
      }
    }
    const wikiMap = new Map;
    for (const article of articles) {
      const wikiKey = article.wikiProject;
      if (!wikiMap.has(wikiKey)) {
        wikiMap.set(wikiKey, { count: 0, pageviews: 0 });
      }
      const stats = wikiMap.get(wikiKey);
      stats.count += 1;
      if (article.pageviews.length > 0 && article.pageviews[0].cumulativeViews) {
        stats.pageviews += article.pageviews[0].cumulativeViews;
      }
    }
    const wikiStats = Array.from(wikiMap.entries()).map(([wiki, stats]) => ({
      wiki,
      count: stats.count,
      pageviews: stats.pageviews
    })).sort((a2, b2) => a2.wiki.localeCompare(b2.wiki));
    const responseData = OutreachArticleStatsResponseSchema.parse({
      totalArticles,
      totalPageviews,
      uniqueWikis: wikiMap.size,
      wikiStats
    });
    return c.json({
      success: true,
      data: responseData
    }, 200);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error fetching outreach articles stats:", message);
    return c.json({
      success: false,
      error: "Failed to fetch statistics",
      details: message
    }, 500);
  }
});
outreachRoutes.post("/sync", async (c) => {
  try {
    const body = OutreachSyncSchema.parse(await c.req.json());
    const job = await prisma.syncJob.create({
      data: {
        jobType: "editors",
        status: "pending"
      }
    });
    setTimeout(async () => {
      try {
        const result = await outreachSyncService2.syncEditorsFromDashboard(body.school, body.slug);
        await prisma.syncJob.update({
          where: { id: job.id },
          data: {
            status: "completed",
            completedAt: new Date,
            metadata: result
          }
        });
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        console.error("Outreach sync failed:", errorMessage);
        await prisma.syncJob.update({
          where: { id: job.id },
          data: {
            status: "failed",
            completedAt: new Date,
            error: errorMessage
          }
        });
      }
    }, 0);
    return c.json({
      success: true,
      data: {
        jobId: job.id,
        status: "accepted"
      }
    }, 202);
  } catch (error) {
    if (error instanceof SyntaxError) {
      return c.json({
        success: false,
        error: "Invalid request body"
      }, 400);
    }
    if (error instanceof Error && error.name === "ZodError") {
      return c.json({
        success: false,
        error: "Validation error",
        details: error.message
      }, 400);
    }
    const message = error instanceof Error ? error.message : String(error);
    console.error("Error triggering outreach sync:", message);
    return c.json({
      success: false,
      error: "Failed to trigger sync",
      details: message
    }, 500);
  }
});

