// src/middleware/error-handler.ts
var formatError = (code, message) => ({
  success: false,
  error: { code, message }
});
var errorHandler2 = (err, c) => {
  if (err instanceof ZodError) {
    return c.json(formatError("validation_error", err.message), 400);
  }
  if (err instanceof exports_prismaNamespace.PrismaClientKnownRequestError) {
    if (err.code === "P2025") {
      return c.json(formatError("not_found", "Resource not found"), 404);
    }
  }
  console.error(err);
  return c.json(formatError("internal_error", "Internal server error"), 500);
};

// src/jobs/scheduler.ts
var import_node_cron = __toESM(require_node_cron(), 1);
init_utils();
var schedule = process.env.SYNC_SCHEDULE ?? "0 2 * * *";
var outreachSchool = process.env.OUTREACH_SCHOOL ?? "OKA";
var outreachSlug = process.env.OUTREACH_SLUG ?? "OKA";
var outreachSchedule = process.env.OUTREACH_ARTICLE_SYNC_SCHEDULE ?? "0 3 * * *";
var startScheduler = () => {
  const wikimediaClient2 = new WikimediaClient({
    baseUrl: "https://en.wikipedia.org"
  });
  const syncService2 = new SyncService(prisma, wikimediaClient2);
  import_node_cron.default.schedule(schedule, async () => {
    try {
      await syncService2.runFullSync();
    } catch (error) {
      console.error("Scheduled sync failed", error);
    }
  });
  const dashboardClient4 = new OutreachDashboardClient({
    baseUrl: "https://outreachdashboard.wmflabs.org"
  });
  const outreachArticleSyncService3 = new OutreachArticleSyncService(prisma, dashboardClient4);
  import_node_cron.default.schedule(outreachSchedule, async () => {
    console.log(`[Scheduler] Starting outreach article sync (school=${outreachSchool}, slug=${outreachSlug})`);
    try {
      const result = await outreachArticleSyncService3.syncArticlesFromDashboard(outreachSchool, outreachSlug);
      console.log(`[Scheduler] Outreach article sync completed: ${result.imported} imported, ${result.updated} updated, ${result.errors} errors`);
    } catch (error) {
      console.error("[Scheduler] Outreach article sync failed:", error);
    }
  });
  console.log(`[Scheduler] Outreach article sync scheduled: ${outreachSchedule}`);
};

